// Ground + rain adapter: the wet ground, puddles, rain rings, planar mirror and rain particles come from the
// Saltline port (js/sl/ground-sl.js, generated by tools/port-sl-ground.js). This file builds the textures,
// hands the module Ga Chìm's camera, quality, interiors and storm, and answers puddle queries for gameplay.
import * as THREE from '../vendor/three.module.min.js';
import { buildMask, buildDetail, dataTexture, buildMarks, buildApron, buildPlanar, buildRain, sampleMask, MASK_RECT } from './sl/ground-sl.js';
import { noMask, U } from './mats.js';

export function buildGround(G) {
  const r = G.renderer;
  const aniso = Math.min(8, r.capabilities.getMaxAnisotropy ? r.capabilities.getMaxAnisotropy() : 1);
  const n = 1024;
  const mask = buildMask(n);
  const maskTex = dataTexture(mask, n, { repeat: false, aniso: 2 });
  const dn = G.quality.tex >= 1024 ? 512 : 256;
  const { det, nrm } = buildDetail(dn);
  const black = new THREE.DataTexture(new Uint8Array([0, 0, 0, 255]), 1, 1); black.needsUpdate = true;
  const tex = { mask: maskTex, detail: dataTexture(det, dn, { aniso }), detailN: dataTexture(nrm, dn, { aniso }), marks: buildMarks(64, aniso), black };
  const interiorBoxes = G.level.dryZones.map((z, i) => {
    const iz = U.uIndoor.value[i]; if (!iz || !(iz.z > 0)) return null;
    return { min: new THREE.Vector3(iz.x - iz.z, 0, iz.y - iz.w), max: new THREE.Vector3(iz.x + iz.z, z.h, iz.y + iz.w) };
  }).filter(Boolean);
  const shim = {
    mats: { uniforms: { wet: U.uRain } },
    quality: { rain: G.quality.rainQ ?? 0.8, planar: G.quality.planar ?? 0.5 },
    rng: { fork: () => Math.random },
    get camera() { return G.camera; },
    renderer: r,
    render: {
      resolution: null,
      renderWorld: (cam, target) => {
        const prev = r.getRenderTarget();
        r.setRenderTarget(target); r.setClearColor(0x000000, 1); r.clear(true, true, false);
        r.render(G.scene, cam);
        r.setRenderTarget(prev);
      },
    },
    level: { interiorBoxes, skylights: [] },
    events: { emit: (name, d) => { if (name === 'thunder' && G.thunder) G.thunder(d.intensity); } },
  };
  const apron = buildApron(shim, tex);
  // the apron does its own mirror; keep it out of the SSR mask
  noMask(apron.material);
  apron.material.customProgramCacheKey = () => 'saltline-apron-3-nomask';
  const rain = buildRain(shim, tex);
  rain.setRain(1);
  for (const m of [rain.rain, rain.splash]) m.layers.set(0);
  const planar = buildPlanar(shim, apron.uniforms, [apron.mesh, rain.rain, rain.splash]);
  const root = new THREE.Group(); root.name = 'ground';
  root.add(apron.mesh, rain.rain, rain.splash);
  G.scene.add(root);
  const inInterior = (x, z) => interiorBoxes.some((b) => x > b.min.x && x < b.max.x && z > b.min.z && z < b.max.z);
  const inMask = (x, z) => x > MASK_RECT.x0 && x < MASK_RECT.x0 + MASK_RECT.size && z > MASK_RECT.z0 && z < MASK_RECT.z0 + MASK_RECT.size;
  let t = 0;
  const api = {
    apron, rain, planar, mesh: rain.rain, splash: rain.splash,
    puddleDepth(x, z) { return !inMask(x, z) || inInterior(x, z) ? -0.2 : 0.5 - sampleMask(mask, n, x, z, 0); },
    isPuddle(x, z) { return api.puddleDepth(x, z) > 0.015; },
    prePass(renderer, camera) { planar.pass(renderer, G.scene, camera); },
    update(dt) { t += dt; rain.update(dt); apron.uniforms.uTime.value = t; apron.uniforms.uRain.value = rain.rainLevel * U.uRain.value; },
  };
  return api;
}
